from durations import format_duration


def test_formats_hours_and_minutes():
    assert format_duration(5400) == "1h30m"


def test_formats_zero():
    assert format_duration(0) == "0s"


import pytest
import durations


def test_parse_hours_and_minutes():
    assert durations.parse_duration("1h30m") == 5400


def test_parse_seconds():
    assert durations.parse_duration("45s") == 45


def test_parse_hours():
    assert durations.parse_duration("2h") == 7200


def test_parse_empty_raises():
    with pytest.raises(ValueError):
        durations.parse_duration("")


def test_parse_unreadable_raises():
    with pytest.raises(ValueError):
        durations.parse_duration("10x")

